/**
 * Place Map's service worker.
 *
 * Written out rather than generated by a plugin: what it does fits on a page,
 * and a cache that misbehaves is very hard to debug through a build step. The
 * same reasoning as the bot having no framework.
 *
 * It does three things and deliberately no more:
 *
 *   1. Serves the build's own static files from cache. They carry a content
 *      hash in the filename, so a cached one is never the wrong one.
 *   2. Keeps the last pages someone visited, and shows them again when the
 *      network is gone. A directory is useful read-only: the address and the
 *      opening hours of a place you looked at yesterday do not need a signal.
 *   3. Falls back to a plain offline page when a page was never visited.
 *
 * What it does NOT do is cache the API. Place data changes, "open now" is
 * decided from the clock, and a stale answer about whether somewhere is open
 * is worse than an honest "you are offline".
 */

// Bumped when this file changes: the old caches are dropped on activate.
const VERSION = 'v2'
const STATIC = `place-map-static-${VERSION}`
const PAGES = `place-map-pages-${VERSION}`

// A plain file, not a page: it is served under whatever address failed, and
// a React page served that way hydrates against the wrong route and replaces
// itself with an error. See the comment in offline.html.
const OFFLINE_URL = '/offline.html'

/** Enough for a browse of a few dozen places without growing without end. */
const MAX_PAGES = 40

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC)
      await cache.addAll([OFFLINE_URL, '/logo.svg'])
      // The new worker takes over as soon as it is ready; waiting for every
      // tab to close means a fix can sit unused for days.
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([STATIC, PAGES])
      await Promise.all(
        (await caches.keys()).map((name) =>
          name.startsWith('place-map-') && !keep.has(name) ? caches.delete(name) : undefined,
        ),
      )
      await self.clients.claim()
    })(),
  )
})

/** Oldest entries go first, so one long browse cannot fill the device. */
async function trim(cacheName, max) {
  const cache = await caches.open(cacheName)
  const keys = await cache.keys()
  for (const key of keys.slice(0, Math.max(0, keys.length - max))) {
    await cache.delete(key)
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event

  // Only plain page and asset reads. A POST, or anything cross-origin - the
  // API, the image CDN, the map tiles - goes straight to the network.
  if (request.method !== 'GET') return
  if (new URL(request.url).origin !== self.location.origin) return

  // The build's own files: hashed names, so cache-first is safe and saves the
  // request entirely.
  if (request.url.includes('/_next/static/')) {
    event.respondWith(
      (async () => {
        const hit = await caches.match(request)
        if (hit) return hit

        const response = await fetch(request)
        if (response.ok) (await caches.open(STATIC)).put(request, response.clone())
        return response
      })(),
    )
    return
  }

  // Everything that is not a page: serve it from the precache if it is there,
  // otherwise just fetch it. Without this the offline page rendered with a
  // broken logo - the file was in the cache, but nothing looked for it.
  if (request.mode !== 'navigate') {
    event.respondWith(
      caches
        .match(request, { cacheName: STATIC })
        .then((hit) => hit || fetch(request)),
    )
    return
  }

  // Pages: the network decides, and the cache is what is left when there is
  // no network. Never the other way round - a cached page would otherwise
  // outlive an edit for as long as the device keeps it.
  event.respondWith(
    (async () => {
      try {
        const response = await fetch(request)
        if (response.ok) {
          const cache = await caches.open(PAGES)
          await cache.put(request, response.clone())
          await trim(PAGES, MAX_PAGES)
        }
        return response
      } catch {
        const cached = await caches.match(request)
        if (cached) return cached

        const offline = await caches.match(OFFLINE_URL)
        if (offline) return offline

        return new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } })
      }
    })(),
  )
})
